<?php

namespace Database\Seeders;

/** Seeds `donation_campaigns` from database/seeders/data/donation_campaigns.json (generated by scripts/export-seed-data.ts in the frontend repo). */
class DonationCampaignsSeeder extends ContentSeederBase
{
    public const TABLE = 'donation_campaigns';

    public function run(): void
    {
        if (! $this->tableReady(self::TABLE)) {
            return;
        }
        $images = ['image' => 'donation-campaigns'];
        $keyCol = $this->hasColumn(self::TABLE, 'slug') ? 'slug' : 'name_ar';

        foreach ($this->json('donation_campaigns') as $row) {
            if (empty($row[$keyCol])) {
                continue;
            }
            $this->upsertFillEmpty(self::TABLE, [$keyCol => $row[$keyCol]], $row, $images);
        }

        $this->report(self::TABLE);
    }
}
